def normalize_scores_minmax(scores):
    """
    Min-max normalize a list of scores to [0, 1].

    If all scores are equal, returns 0.5 for all.
    """

    if not scores:
        return []

    min_s = min(scores)
    max_s = max(scores)
    span = max_s - min_s

    if span == 0:
        return [0.5] * len(scores)

    return [
        (s - min_s) / span
        for s in scores
    ]
